    <div class="absolute-ownership" style="
      background: rgba(148, 0, 211, 0.5);
      padding: 30px;
      border-radius: 25px;
      border: 4px dashed #9400d3;
      box-shadow: 0 0 25px rgba(148, 0, 211, 0.6);
    ">
