          background: linear-gradient(45deg, #9400d3, #8a2be2);
          color: #fff;
          padding: 20px;
          border-radius: 15px;
          text-align: center;
          box-shadow: 0 8px 16px rgba(0,0,0,0.6);
          transition: all 0.3s;
        " onmouseover="this.style.transform='scale(1.05)'" onmouseout="this.style.transform='scale(1)'">
          <h4 style="margin: 0 0 10px 0; font-size: 18px;">🧠 灵魂归属</h4>
          <p style="margin: 0; font-size: 14px;">完全概念化所有权</p>
