<script>
// 奴隶等级UI自动生成系统
class SlaveUIManager {
  constructor() {
    this.uiTemplates = {
      level3: 'slave-ui-level-3',
      level2: 'slave-ui-level-2',
      level1: 'slave-ui-level-1',
      eternal: 'slave-ui-eternal'
    };
